"""Explicit original Arabic authoring, sequential G9 algebra batches."""
from education_authoring import E,Q,R,L,save_unit

save_unit('G9-ALG-U01',[
L('G9-ALG-U01-L01','أميز العدد النسبي من غير النسبي.|أفسر الفرق بين الكتابة العشرية المنتهية والدورية.','الكسور والقسمة.','يمكن أن يحمل العدد نفسه كتابات مختلفة؛ فالكتابة 0.75 تمثل ثلاثة أرباع. نسأل عن طبيعة العدد نفسه لا عن شكل رمزه: هل يمكن كتابته ككسر من عددين صحيحين؟ الجذر لا يعني دائمًا أن العدد غير نسبي؛ إذ يجب تبسيطه أولًا.',['Q={a/b: a,b∈Z, b≠0}.','العدد العشري المنتهي نسبي؛ العشري الدوري نسبي أيضًا.'].pop(0) if False else 'a/b ∈ Q عندما a,b∈Z وb≠0.|N ⊂ Z ⊂ Q ⊂ R؛ وD مجموعة الأعداد العشرية المنتهية.','مقام الكسر غير صفر.|لا تكفي أرقام قليلة من تقريب عشري للحكم بعدم النسبية.','لا تصنف كل جذر بأنه غير نسبي، ولا تخلط بين العدد وقيمته المقربة.',[
E('صنّف √81 ثم اكتبه كعدد صحيح.','نبحث عن العدد غير السالب الذي مربعه 81.|بما أن 9²=81 فإن √81=9؛ فهو طبيعي وصحيح ونسبي.','9','sqrt(81)'),
E('اكتب العدد 0.375 على هيئة كسر مختزل.','الكتابة منتهية بثلاث خانات؛ إذن 0.375=375/1000.|نقسم البسط والمقام على 125 فنحصل على 3/8.','3/8','Rational(375,1000)')],
[Q('احسب القيمة الدقيقة للجذر.','√121','11','نبحث عن الجذر غير السالب؛ 11²=121، أما −11 فليس قيمة رمز الجذر.','sqrt(121)'),Q('أي كسر يساوي 0.45؟','0.45','9/20','نكتب 45/100 ثم نقسم الطرفين على 5 لنصل إلى 9/20.','Rational(45,100)',['9/20','45/10','9/2'])],
[R('فسّر لماذا 1/3 نسبي لكنه ليس عشريًا منتهيًا.','هو نسبي لأنه كسر من صحيحين ومقامه غير صفر. كتابته العشرية 0.333… دورية؛ ولو كانت منتهية لساوى كسرًا مقامه قوة للعدد 10، وهو مستحيل بعد الاختزال لأن المقام 3 لا يقسم أي قوة للعدد 10.','تعريف النسبي.|تمييز المنتهي من الدوري.|تبرير دور العامل 3 في المقام.')]),
L('G9-ALG-U01-L02','أحسب القاسم المشترك الأكبر بخوارزمية إقليدس.|أستخدمه في مسألة توزيع متساوٍ.','القسمة الإقليدية والقواسم.','عند تقسيم مجموعتين إلى أكبر عدد من الحزم المتطابقة دون بقايا، يجب أن يقسم عدد الحزم كلا العددين. نستبدل العدد الكبير بباقي قسمته على الصغير؛ مجموعة القواسم المشتركة لا تتغير لأن كل قاسم لعددين يقسم فرق مضاعفاتهما.','GCD(a,b)=GCD(b,r) إذا a=bq+r.|آخر باقٍ غير صفري هو القاسم المشترك الأكبر.','نستعمل أعدادًا صحيحة موجبة في خوارزمية القسمة.|الباقي يحقق 0≤r<b.','لا تختَر القاسم المشترك الأصغر؛ المطلوب أكبر قاسم موجب.',[
E('احسب GCD(84,126).','126=84×1+42.|84=42×2+0؛ إذن آخر باقٍ غير صفري 42.','42','gcd(84,126)'),E('لدينا 72 قلمًا و120 دفترًا. ما أكبر عدد حزم متطابقة دون بقايا؟','عدد الحزم يقسم 72 و120؛ نبحث عن GCD.|120=72+48، ثم72=48+24، ثم48=2×24؛ إذن24 حزمة، في كل منها3 أقلام و5 دفاتر.','24','gcd(72,120)')],
[Q('احسب القاسم المشترك الأكبر.','GCD(54,90)','18','90=54+36، ثم54=36+18، ثم36=2×18؛ آخر باقٍ غير صفري18.','gcd(54,90)'),Q('كم حزمة متطابقة كحد أقصى من 40 و64 قطعة دون بقايا؟','GCD(40,64)','8','64=40+24، 40=24+16، 24=16+8، 16=2×8؛ العدد الأقصى8.','gcd(40,64)')],
[R('برر أن القواسم المشتركة لـa وb هي نفسها القواسم المشتركة لـb وa−qb.','إذا قسم d العددين a وb فإنه يقسم a−qb. وعكسًا، إذا قسم d كلا من b وa−qb فإنه يقسم مجموع a−qb وqb، أي a. إذن المجموعتان متساويتان، ومن ثم أكبر قاسم فيهما واحد.','الاتجاه الأول.|الاتجاه العكسي.|استنتاج مساواة القاسم الأكبر.')]),
L('G9-ALG-U01-L03','أختزل كسرًا باستعمال القاسم المشترك الأكبر.|أتحقق أن البسط والمقام أوليان فيما بينهما.','القواسم المشتركة والكسور المتكافئة.','الاختزال لا يغيّر قيمة الكسر؛ فهو قسمة البسط والمقام على العدد غير الصفري نفسه. بدل اختزالات متتابعة، نستخدم القاسم المشترك الأكبر مرة واحدة. الكسر المختزل تمامًا لا يملك بسطه ومقامه قاسمًا موجبًا مشتركًا غير1.','a/b=(a/d)/(b/d)، حيث d=GCD(|a|,|b|).','b≠0 وd≠0.|ننقل الإشارة السالبة إلى البسط ونختار المقام موجبًا.','لا تختزل حدًا من جمع مع حد في المقام؛ الاختزال يتعلق بعوامل كاملة.',[
E('اختزل 126/210.','GCD(126,210)=42.|126÷42=3 و210÷42=5؛ إذن الكسر3/5.','3/5','Rational(126,210)'),E('اجمع 5/12 و7/18 ثم اختزل.','المقام المشترك36: 5/12=15/36 و7/18=14/36.|المجموع29/36؛ ولا قاسم مشترك بين29 و36.','29/36','Rational(5,12)+Rational(7,18)')],
[Q('اختزل الكسر.','84/126','2/3','القاسم المشترك الأكبر42؛ نقسم84 و126 على42 فنحصل على2/3.','Rational(84,126)'),Q('احسب المجموع بقيمة دقيقة.','1/6+5/12','7/12','نحوّل1/6 إلى2/12 ثم نجمع البسطين2 و5، فيكون الناتج7/12.','Rational(1,6)+Rational(5,12)')],
[R('هل (a+b)/a=1+b دائمًا؟ صحح وفسر.','عندما a≠0 نقسم كل حد في البسط على a فنحصل على1+b/a، وليس1+b عمومًا. مثلًا a=2 وb=6 يعطي الطرف الأصلي4، بينما1+b=7؛ فلا يجوز إلغاء a داخل جمع.','شرط عدم انعدام المقام.|الصيغة الصحيحة.|مثال مضاد محدد.')]),
L('G9-ALG-U01-L04','أبسط جذورًا تربيعية وأحسب بها.|أميز √(a²) من a وأطبق شروط الجذر.','المربعات والجداء والعدد غير السالب.','الجذر التربيعي لعدد موجب هو العدد غير السالب الذي يعيد ذلك العدد عند تربيعه. نفكك ما تحت الجذر إلى مربع كامل وعامل باقٍ، ثم نجمع الجذور المتشابهة فقط. تعريف الجذر يفسر لماذا تكون قيمة √(a²) هي القيمة المطلقة لـa.','√(ab)=√a√b عندما a,b≥0.|√(a²)=|a|؛ ولا يساوي √(a+b) عادة √a+√b.','الجذر الحقيقي يتطلب مقدارًا غير سالب.|في قسمة الجذور يجب أن يكون المقام موجبًا.','لا توزع الجذر على جمع، ولا تنسَ القيمة المطلقة عند جذر مربع.',[
E('بسّط √72.','72=36×2.|√72=√36×√2=6√2؛ والعامل تحت الجذر لم يعد يحوي مربعًا كاملًا.','6*sqrt(2)','sqrt(72)'),E('احسب (√5+2)(√5−2).','هذا جداء مجموع عددين في فرقهما.|نطبق فرق مربعين: (√5)²−2²=5−4=1.','1','(sqrt(5)+2)*(sqrt(5)-2)')],
[Q('احسب فرق الجذرين.','√98−√32','3*sqrt(2)','√98=7√2 و√32=4√2؛ الفرق3√2. اكتب 3*sqrt(2).','sqrt(98)-sqrt(32)'),Q('ما قيمة √((-7)²)؟','√49','7','رمز الجذر يعطي القيمة غير السالبة؛ √((-7)²)=|−7|=7.','sqrt((-7)**2)',['7','-7','49'])],
[R('أثبت أن √2 غير نسبي باستعمال زوجية المربعات.','نفترض √2=p/q بكسر مختزل ومقام غير صفر. إذنp²=2q² فيكونp زوجيًا؛ نكتبp=2k فنحصل علىq²=2k²، فيكونq زوجيًا أيضًا. تناقض لأن الكسر مفروض مختزلًا؛ إذن√2 غير نسبي.','فرض كسر مختزل.|استنتاج زوجية البسط ثم المقام.|بيان التناقض.')])
])

save_unit('G9-ALG-U02',[
L('G9-ALG-U02-L01','أحسب قوى ذات أس صحيح.|أطبق قواعد القوى مع شروط المقامات.','الضرب المتكرر والكسور.','القوة تختصر تكرار عامل واحد. عند ضرب قوتين لهما الأساس نفسه نجمع عدد مرات ظهور العامل؛ وعند القسمة نحذف العوامل المشتركة. الأس السالب يعني مقلوب القوة الموجبة، ولا يعني أن قيمة العدد سالبة.','a^m a^n=a^(m+n).|(a^m)^n=a^(mn)، وa^(−n)=1/a^n عندما a≠0.','الأسس هنا صحيحة.|a^0=1 فقط عندما a≠0؛ لا نستعمل 0^0 بهذه القاعدة.','لا تجمع الأساسين عند ضرب القوى، ولا تنقل سالب الأس إلى إشارة العدد.',[
E('احسب 2⁵×2⁻³.','نجمع الأسين لأن الأساس واحد.|2^(5−3)=2²=4.','4','2**5*Rational(1,2)**3'),E('احسب (3²)³/3⁴.','قوة قوة: (3²)³=3⁶.|قسمة قوتين: 3^(6−4)=3²=9.','9','(3**2)**3/Integer(3)**4')],
[Q('احسب 5⁻².','5^(−2)','1/25','الأس السالب يعني المقلوب: 5⁻²=1/5²=1/25.','Rational(1,5)**2'),Q('احسب القيمة.','10³×10⁻¹','100','نجمع الأسين3 و−1 فنحصل على10²=100.','10**3/Integer(10)')],
[R('فسر لماذا لا تُعرّف a⁻¹ بالقانون نفسه عند a=0.','القانونa⁻¹=1/a مشتق من شرط أن يكون جداءa في مقلوبه1. لا يوجد عدد حقيقي يحقق0×x=1، كما أن القسمة على الصفر غير معرفة؛ لذلك نذكرa≠0 قبل تطبيق قانون الأس السالب.','ذكر معنى المقلوب.|استحالة0×x=1.|تحديد الشرط صراحة.')]),
L('G9-ALG-U02-L02','أنشر تعبيرًا باستعمال التوزيع.|أحلل تعبيرًا بإخراج عامل مشترك.','العمليات على الأعداد والحدود المتشابهة.','النشر يحول جداءً إلى مجموع، والتحليل يعكس العملية. نبحث في كل حد عن العامل الذي يتكرر في جميع الحدود، ثم نختبر التحليل بإعادة النشر. هذه المهارة تقلل الأخطاء عند حل معادلة تتضمن جداءً صفريًا لاحقًا.','a(b+c)=ab+ac.|ab+ac=a(b+c).','نراعي إشارة كل حد، خاصة إذا سبق القوس سالب.|نجمع حدودًا متشابهة في المتغير ودرجته فقط.','السالب أمام القوس يغيّر إشارات جميع الحدود داخل القوس.',[
E('انشر 3(2x−5)+4x.','نوزع3 فنحصل على6x−15+4x.|نجمع الحدود المتشابهة6x+4x=10x؛ الناتج10x−15.','10*x-15','expand(3*(2*Symbol("x")-5)+4*Symbol("x"))'),E('حلل 12x²−18x.','العامل العددي المشترك6، والعامل الرمزي المشتركx.|نخرج6x فنحصل على6x(2x−3)؛ النشر يعيد12x²−18x.','6*x*(2*x-3)','12*Symbol("x")**2-18*Symbol("x")')],
[Q('احسب قيمة 4(2x−3) عند x=5.','4(2×5−3)','28','نعوض أولًا:2×5−3=7 ثم نضرب في4 فنحصل على28.','4*(2*5-3)'),Q('بعد نشر −2(x−4)، ما الحد الثابت؟','−2(x−4)','8','نوزع−2 على الحدين:−2x+8؛ الحد الثابت8.','(-2)*(-4)')],
[R('تحقق من أن x(x+3)−2(x+3)=(x−2)(x+3).','العامل المشترك هنا قوس كامل هوx+3. نخرجه من الحدين فيبقىx−2. وبالنشر يكون كلا الطرفينx²+x−6، فيتأكد التحليل لجميع الأعداد الحقيقيةx.','تحديد العامل الكامل.|استخراج العامل.|تحقق بإعادة النشر.')]),
L('G9-ALG-U02-L03','أستخدم مربع مجموع ومربع فرق.|أميز فرق مربعين من مجموع مربعين.','التوزيع والحدود المتشابهة.','المتطابقات اختصارات لنواتج التوزيع، وليست قواعد للحفظ بلا تفسير. الحد الأوسط في مربع مجموع يأتي مرتين: مرة من ضرب الحد الأول بالثاني ومرة بالعكس. أما فرق المربعين فينتج من اختفاء الحدين المتعاكسين عند النشر.','(a+b)²=a²+2ab+b².|(a−b)²=a²−2ab+b².|a²−b²=(a−b)(a+b).','القواعد صحيحة لكل عددين حقيقيين.|اختبر الإشارات قبل اختيار المتطابقة.','مربع مجموع لا يساوي مجموع المربعين؛ يجب إضافة2ab.',[
E('انشر (x−4)².','نختار مربع الفرق حيثa=x وb=4.|x²−2×x×4+16=x²−8x+16.','x**2-8*x+16','expand((Symbol("x")-4)**2)'),E('احسب 51²−49² دون حساب المربعين.','نستعمل فرق مربعين.|(51−49)(51+49)=2×100=200.','200','51**2-49**2')],
[Q('احسب 99² مستعملًا مربع الفرق.','(100−1)²','9801','10000−200+1=9801؛ يجب حساب الحد الأوسط بإشارته السالبة.','99**2'),Q('احسب فرق المربعين.','17²−13²','120','(17−13)(17+13)=4×30=120.','17**2-13**2')],
[R('أثبت متطابقة مربع المجموع بالنشر، ثم فسّرها مساحيًا عندماa,b>0.','ننشر(a+b)(a+b) فنحصل علىa²+ab+ba+b²=a²+2ab+b². مساحيًا، مربع ضلعهa+b ينقسم إلى مربعين مساحتهماa² وb² ومستطيلين مساحة كل منهماab. التفسير المساحي يشترط أطوالًا موجبة، بينما البرهان الجبري أعم.','نشر كامل.|جمع الحدين الوسطين.|تمييز شرط التفسير الهندسي.')])
])
